function setNested(target, dottedPath, value) {
  const parts = dottedPath.split(".");
  let cursor = target;
  for (const part of parts.slice(0, -1)) {
    if (!cursor[part] || typeof cursor[part] !== "object") cursor[part] = {};
    cursor = cursor[part];
  }
  cursor[parts.at(-1)] = value;
}

let changed = 0;

for (const [namespace, namespaceRows] of Object.entries(rows)) {
  for (const [localeIndex, locale] of locales.entries()) {
    const filePath = path.join(root, "messages", locale, `${namespace}.json`);
    const catalog = JSON.parse(fs.readFileSync(filePath, "utf8"));
    for (const row of namespaceRows) {
      const key = row[0];
      const value = row[localeIndex + 1];
      if (catalog[key] !== value) {
        catalog[key] = value;
        changed += 1;
      }
    }
    if (shouldWrite) {
      const sorted = Object.fromEntries(
        Object.entries(catalog).sort(([left], [right]) => left.localeCompare(right)),
      );
      fs.writeFileSync(filePath, `${JSON.stringify(sorted, null, 2)}\n`, "utf8");
    }
  }
}

for (const locale of locales) {
  const localeIndex = locales.indexOf(locale);
  const byNamespace = new Map();
  for (const [namespace, dottedPath, ...values] of targetedRows) {
    const namespaceRows = byNamespace.get(namespace) || [];
    namespaceRows.push([dottedPath, values[localeIndex]]);
    byNamespace.set(namespace, namespaceRows);
  }
  for (const [namespace, namespaceRows] of byNamespace) {
    const filePath = path.join(root, "messages", locale, `${namespace}.json`);
    const catalog = JSON.parse(fs.readFileSync(filePath, "utf8"));
    for (const [dottedPath, value] of namespaceRows) {
      const current = dottedPath.split(".").reduce((cursor, part) => cursor?.[part], catalog);
      if (current !== value) {
        setNested(catalog, dottedPath, value);
        changed += 1;
      }
    }
    if (shouldWrite) {
      fs.writeFileSync(filePath, `${JSON.stringify(catalog, null, 2)}\n`, "utf8");
    }
  }
}

console.log(`${shouldWrite ? "Applied" : "Pending"}: ${changed} multilingual copy update(s).`);
if (!shouldWrite && changed > 0) process.exitCode = 1;
